const probeResults = await Promise.all(
  sources.map(async (src) => {
    let toplevel: string;
    try {
      toplevel = normPath((await runGit(src, "rev-parse", "--show-toplevel")).trim());
    } catch {
      return null;
    }
    let list: string;
    try {
      [toplevel, list] = await Promise.all([
        Promise.resolve(toplevel),
        runGit(src, "worktree", "list", "--porcelain"),
      ]);
    } catch {
      return null;
    }
    return { toplevel, entries: parseWorktreePorcelain(list) };
  }),
);
for (const r of probeResults) {
  if (!r) continue;
  toplevels.add(r.toplevel);
  for (const w of r.entries) {
    entries.push({ toplevel: r.toplevel, path: w.path, branch: w.branch, head: w.head });
  }
}

